import { test } from "../fixtures/pages.fixture";
import { productData } from "../test-data/products.data";

// Scenario 3: own test case. The test was generated by AI and then reviewed.
// "Review" comments below follow the review points from the assignment.

test.describe("IKEA Shop: product search", () => {
  // Review (naming): the test name describes user-visible behaviour, not implementation details.
  // Review (POM): the homePage fixture opens the site and accepts cookies, so the spec contains only scenario steps.
  test("searched product can be found and opened", async ({ homePage }) => {
    const searchResults =
      await test.step("Search for the product and check the results", async () => {
        // Review (hardcoded values): the search term comes from test-data, not from the spec.
        const resultsPage = await homePage.header.searchFor(
          productData.searchTerm,
        );
        // Review (locators): results are scoped to product card titles (h3 > link) inside main.
        // The first AI version used every link in main, which could give a false positive.
        await resultsPage.expectResultsContain(productData.searchTerm);
        return resultsPage;
      });

    await test.step("Open the first matching product and check its name", async () => {
      // Review (separation of logic): navigation returns the next page object, so the spec never creates page objects itself.
      const productPage = await searchResults.openFirstProduct(
        productData.searchTerm,
      );
      // Review (assertions): web-first expect with auto-waiting, no isVisible() checks and no fixed sleeps.
      await productPage.expectNameContains(productData.searchTerm);
    });

    // Review (stability): the test depends on the live catalogue; if BILLY is renamed or removed, only test data changes.
    // Review (maintainability): checking another product means adding data, not new test code.
  });
});
